 const chapters=$('chapters');chapters.replaceChildren();
 MISSIONS.forEach((m,i)=>{const b=document.createElement('button');b.disabled=!ready||i>save.unlocked;b.className=i===selected?'active':'';b.setAttribute('aria-pressed',String(i===selected));const name=document.createElement('span');name.textContent=`0${i+1}  ${m.title}`;const stars=document.createElement('small');stars.textContent=i>save.unlocked?'未解锁':'★'.repeat(save.stars[i])+'☆'.repeat(3-save.stars[i]);b.append(name,stars);b.onclick=()=>{storeCheckpoint();selected=i;started=false;ended=false;paused=false;resetMission();document.body.classList.remove('playing','paused');$('overlay-kicker').textContent=`CHAPTER 0${i+1}`;$('overlay-title').textContent=m.title;$('overlay-desc').textContent=m.brief;$('start').textContent=checkpoint?.chapter===i?'从检查点继续':'开始本章';$('restart').hidden=checkpoint?.chapter!==i;menu();};chapters.append(b);});
