 const up=$('upgrades');up.replaceChildren();for(const [key,label] of [['armor','装甲 +18'],['reload','装填提速'],['engine','引擎提速']]){const level=save.upgrades[key],b=document.createElement('button');b.textContent=`${label}  ${level}/3　${level===3?'已满级':`需要 ${level+1} 点`}`;b.disabled=level===3||save.credits<level+1||started&&!ended||!!checkpoint;b.onclick=()=>{save=buyUpgrade(save,key);persist();menu();};up.append(b);}
