 if(paused){if(engineGain)engineGain.gain.value=0;audio?.suspend().catch(()=>{});storeCheckpoint();$('overlay-kicker').textContent=`CHAPTER 0${selected+1} / PAUSED`;$('overlay-title').textContent='行动暂停';$('overlay-desc').textContent='当前行动已保存，可以继续或从本章起点重新出发。';$('start').textContent='继续行动';$('restart').hidden=false;menu();$('start').focus();}
 else{initAudio();$('battle').focus();}
