 $('overlay-desc').textContent=success?`${selected===5?'归船穿过晨雾，青岚镇的灯重新亮了。':'下一章已解锁。'} 基础一星；装甲保留 40% 加一星；${convoy?'补给车保留 60%':'留存至少一个修理包'}再加一星。`:reason||'装甲耗尽，可恢复最近检查点，已获得的星章与升级不会丢失。';
 $('start').textContent=success?(selected===5?'重玩终章':'进入下一章'):(checkpoint?.chapter===selected?'恢复检查点':'重试本章');
