 if(!visible||dist>27){while(t.path.length&&Math.hypot(t.path[0].x-t.x,t.path[0].z-t.z)<1.05)t.path.shift();let p=t.path[0];for(let i=1;i<Math.min(7,t.path.length);i++){const candidate=t.path[i],a=Math.atan2(candidate.x-t.x,candidate.z-t.z),d=Math.hypot(candidate.x-t.x,candidate.z-t.z);let ok=true;for(let q=.5;q<=d;q+=.65)if(!bodyClear(nav,t.x+Math.sin(a)*q,t.z+Math.cos(a)*q,a)){ok=false;break;}if(ok)p=candidate;}if(p){const d=angleDelta(t.yaw,Math.atan2(p.x-t.x,p.z-t.z));t.yaw+=clamp(d,-dt,dt);speed=Math.abs(d)<.65?t.config.speed:0;}}
