function hitTank(t,b,p){let damage=t.enemy?40:b.owner.config.damage*(save.difficulty==='easy'?.58:save.difficulty==='hard'?1.25:1);if(t.enemy){if(Math.abs(angleDelta(t.yaw,b.owner.aim+Math.PI))>1.8)damage=54;hits++;damageDealt+=Math.min(t.hp,damage);$('reticle').classList.add('confirmed');toast(damage>40?'后侧装甲命中 +54':'装甲命中 +40');}else damageTaken+=Math.min(t.hp,damage);t.hp=Math.max(0,t.hp-damage);explosion(p);if(!t.enemy)damageFlash=.7;if(t.hp<=0){t.alive=false;t.speed=0;explosion(t.model.position.clone().add(new V(0,1.2,0)),true);if(t.enemy){kills++;for(const material of t.owned)material.color?.multiplyScalar(.32);toast(`敌车击毁 · ${kills}`);storeCheckpoint();}else finish(false);}}
