function simulation(dt){time+=dt;phaseDelay-=dt;smokeTime=Math.max(0,smokeTime-dt);smokeCooldown=Math.max(0,smokeCooldown-dt);repairCooldown=Math.max(0,repairCooldown-dt);updatePlayer(dt);for(const t of tanks){t.reload=Math.max(0,t.reload-dt);if(t.alive){if(t.enemy)updateAI(t,dt);animateTank(t,dt);}else{t.deadAge+=dt;if(t.deadAge<8&&frame%18===0)emit(t.model.position.clone().add(new V(0,1.4,0)),1,true);}}updateBullets(dt);updateMission(dt);checkpointClock+=dt;if(checkpointClock>=8)storeCheckpoint();routeClock-=dt;if(routeClock<=0){updateRoute();routeClock=1.5;}if(smokeTime>0&&frame%9===0)emit(new V(player.x,nav.ground+1,player.z),3,true,1.6);}
